// TH15 v1.00b Stage 4 BossCard1 (普通中断链第2攻击)
// 源：st04bs.ecl.txt::BossCard1 1180-1320；依赖 BCirC01 471-494、BCirC01_at 502-540、
//     BossCard1_at/at2/at3 1322-1400。入口状态见 Boss 727-767。
const TIME_LIMIT: int = 2524;      // 120 开场缓冲 + 4 帧入口清理 + 源 timerReset 后 2400
const OPENING_BUFFER: int = 120;

const TH15_TALISMAN: int = 528;    // 源 type 11
const TH15_GLOW_BALL: int = 880;   // 源 type 33

// 源 etEx2 type16 STEP：a=60 帧内把当时速度线性降到0，段界 c=1 重新自机狙，恢复 s=4.0。
// !E/!N/!LO 段数 b=1；!H b=2。
xformdef TALISMAN_STEP1 {
    step_speed(0fx, 60);
    wait(60);
    aim_player(0deg);
    set_speed(4fx);
}
xformdef TALISMAN_STEP2 {
    step_speed(0fx, 60);
    wait(60);
    aim_player(0deg);
    set_speed(4fx);
    step_speed(0fx, 60);
    wait(60);
    aim_player(0deg);
    set_speed(4fx);
}

// BCirC01_at：type 11、count 1、固定方向 -pi/2（上）、初速 2.0；
// 每 10 帧一发，共 $A=400 次。角度 -pi/2 + RANDF2*0.08726646（±5°）。
// 出生ANIM a=1 的 4*速度退位移保留：position -= 4*velocity。
async sub bcirc_shooter(color: int) {
    for i in 0..400 {
        var a: angle = 270deg + ((rand(1821) - 910) as angle);
        var ox: fx = 8fx * cos(a);
        var oy: fx = 8fx * sin(a);
        if global(GVAR_RANK) == RANK_HARD {
            _ = fire(TH15_TALISMAN, color, $self_x - ox, $self_y - oy, 2fx, a, TALISMAN_STEP2, none);
        } else {
            _ = fire(TH15_TALISMAN, color, $self_x - ox, $self_y - oy, 2fx, a, TALISMAN_STEP1, none);
        }
        wait(10);
    }
}

// BCirC01：setHurtbox(24,24)/setHitbox(16,16) 的普通圆形换算为半径12/8；
// moveVel(pi/2, 3.0 + RANDF2*0.1) 向下自行离场。子敌走无敌存活路径，
// 死亡回调 BI3/flagExtDmg 不模拟；离场后主任务结束，静默退场并终止射击异步。
async sub bcirc(color: int) {
    set_invuln(65535);
    set_hurtbox(12fx);
    set_hitbox(8fx);
    spawn bcirc_shooter(color);
    var spd: fx = 3fx + ((rand(6554) - 3277) as fx) / 32768;
    move_vel(0, 90deg, spd, EASE_LINEAR);
    wait(200);
}

// BossCard1_at / at2：14 个绝对出生点，间隔 10 帧；!E 仅在 $C=4..9 创建。
sub spawn_row(color: int, x0: fx, dx: fx) {
    var x: fx = x0;
    for i in 0..14 {
        if global(GVAR_RANK) != RANK_EASY || (i >= 4 && i <= 9) {
            _ = spawn_enemy(x, -32fx, 300, 0, 1000, 0, bcirc(color));
        }
        x = x + dx;
        wait(10);
    }
}

// BossCard1_at3（仅非Lunatic）：type 33、色1、8路固定环、角 pi/2、速 2.0，
// 每 120 帧一轮，共 400 轮。ANIM 退位移同样并入出生点。
async sub ring_bullets() {
    for i in 0..400 {
        for j in 0..8 {
            var a: angle = 90deg + (j * 8192) as angle;
            _ = fire(TH15_GLOW_BALL, 1, $self_x - 8fx * cos(a), $self_y - 8fx * sin(a),
                     2fx, a, none, none);
        }
        wait(120);
    }
}

// 真实Boss：入口(0,128)、框 48/40（半径24/20），4帧入口清理后开始 2400 帧段。
// 分支为源难度掩码：Lunatic 走 at/at2 交替（等待0/180/0/180）；
// E/N/H 额外启动 at3，并循环 at/wait120/at2/wait120。
async sub boss_card() {
    set_invuln(65535);
    set_hitbox(24fx);
    set_hurtbox(20fx);
    wait(4);
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    wait(90);
    if global(GVAR_RANK) == RANK_LUNATIC {
        loop {
            spawn_row(2, -192fx, 32fx);
            spawn_row(4, 192fx, -32fx);
            wait(180);
            spawn_row(4, 192fx, -32fx);
            spawn_row(2, -192fx, 32fx);
            wait(180);
        }
    } else {
        spawn ring_bullets();
        loop {
            spawn_row(2, -192fx, 32fx);
            wait(120);
            spawn_row(4, 192fx, -32fx);
            wait(120);
        }
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    _ = spawn_enemy(0fx, 128fx, 2300, 0, 0, 0, boss_card);
    loop { wait(1); }
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    kill_all_enemies(KILL_SILENT);
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
